   above it is cut to one row each, the systems become one grouped card
   instead of twelve floating tiles, and the sheet opens on where you are. */
@media (max-width:980px){
  .sheetin{max-height:88vh;max-height:88dvh}
  .sheethead{margin:0 0 8px}
  .sheethead b{font-size:19px}
  .sheetin .shelfpick{margin:0 0 10px;display:block}
  .sheetin .shelfpick .lbl{display:none}
  .sheetin .shelfpick .seg{display:flex;flex-wrap:nowrap;gap:0;padding:3px;border-radius:12px}
  .sheetin .shelfpick button{flex:1;padding:8px 4px;font-size:10px;letter-spacing:.9px;white-space:nowrap}
  .sheetin .shelfpick button.soon{display:none}
  #msearch{padding:10px 14px;margin:0 0 10px;border-radius:11px}
  .sheetlist{
    padding:0 0 4px;
    -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 8px);
            mask-image:linear-gradient(180deg,transparent 0,#000 8px);
  }
  .sheetgroup{
    border-radius:15px;overflow:hidden;margin:4px 0 0;
    background:linear-gradient(145deg,#F4F5F5 0%,#EEF0F0 55%,#E9EBEB 100%);
    box-shadow:var(--e2);
  }
  .sheetlist details{margin:0;border-radius:0;background:none;box-shadow:none}
  .sheetlist details+details{border-top:1px solid rgba(24,28,30,.08)}
  .sheetlist details[open]{box-shadow:none;background:rgba(255,255,255,.35)}
  .sheetlist summary{padding:13px 14px 13px 16px;font-size:15px}
  .sheetlist summary i{padding:2px 7px;font-size:10.5px}
  .sheetlist a{padding:11px 16px 11px 26px;font-size:14.2px;background:none}
  .sheetlist a.bs{padding-left:26px}
  .sheetlist .msub{background:none}
  /* where you are: the system you were reading, and the brief itself */
  .sheetlist details.here summary .t::after{
    content:"Reading";margin-left:8px;vertical-align:2px;
    font-size:8.5px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--accent);
  }
  .sheetlist a.here{color:var(--ink);font-weight:600;box-shadow:inset 3px 0 0 var(--accent)}
}

